import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public final class Solution {
    private Solution() {}

    public static List<String> transformCatalog(List<String> lines, int batchSize) {
        if (lines == null || batchSize <= 0) throw new IllegalArgumentException("arguments");
        if (lines.isEmpty()) return List.of();
        if (lines.get(0) == null || !lines.get(0).equals("sku|title|section")) {
            throw new IllegalArgumentException("header");
        }
        List<String> result = new ArrayList<>();
        result.add("sku|title|section");
        for (int start = 1; start < lines.size(); start += batchSize) {
            int end = Math.min(lines.size(), start + batchSize);
            for (int i = start; i < end; i++) {
                String line = lines.get(i);
                if (line == null) throw new IllegalArgumentException("null line");
                String[] fields = line.split("\\|", -1);
                if (fields.length != 3) throw new IllegalArgumentException("record " + i);
                for (int j = 0; j < fields.length; j++) fields[j] = fields[j].trim();
                if (fields[0].isEmpty() || fields[1].isEmpty() || fields[2].isEmpty()) {
                    throw new IllegalArgumentException("record " + i);
                }
                result.add(fields[0] + "|" + fields[1].toLowerCase(Locale.ROOT) + "|" + fields[2]);
            }
        }
        return List.copyOf(result);
    }
}

