import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class SolutionTest {
    public static void main(String[] args) {
        List<String> input = new ArrayList<>(List.of(
                "sku|title|section",
                " A1 | red chair | furniture ",
                "B2|i|letters",
                "C3|Mixed Case|General"));
        List<String> snapshot = List.copyOf(input);

        Locale previous = Locale.getDefault();
        List<String> result;
        try {
            Locale.setDefault(Locale.forLanguageTag("tr-TR"));
            result = Solution.transformCatalog(input, 2);
        } finally {
            Locale.setDefault(previous);
        }
        eq(List.of("sku|title|section", "A1|RED CHAIR|furniture", "B2|I|letters",
                "C3|MIXED CASE|General"), result);
        eq(snapshot, input);
        expect(UnsupportedOperationException.class, () -> result.add("D4|X|Y"));
        input.set(1, "changed|changed|changed");
        eq("A1|RED CHAIR|furniture", result.get(1));

        List<String> lines = List.of("sku|title|section", "x|alpha|one", "y|beta|two");
        eq(Solution.transformCatalog(lines, 1), Solution.transformCatalog(lines, 100));
        List<String> empty = Solution.transformCatalog(List.of(), 1);
        eq(List.of(), empty);
        expect(UnsupportedOperationException.class, () -> empty.add("x"));

        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(null, 1));
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(List.of(), 0));
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(lines, -1));
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(List.of("SKU|title|section"), 1));
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(List.of(" sku|title|section"), 1));
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(List.of("sku|title|section", ""), 1));
        for (String bad : List.of("a|b", "a|b|c|d", "|b|c", "a||c", "a|b|", " |b|c", "a| |c")) {
            expect(IllegalArgumentException.class,
                    () -> Solution.transformCatalog(List.of("sku|title|section", bad), 1));
        }
        ArrayList<String> withNull = new ArrayList<>();
        withNull.add("sku|title|section");
        withNull.add(null);
        expect(IllegalArgumentException.class, () -> Solution.transformCatalog(withNull, 1));
    }

    private static void eq(Object expected, Object actual) {
        if (!expected.equals(actual)) throw new AssertionError("expected=" + expected + ", actual=" + actual);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try { action.run(); }
        catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + t, t);
        }
        throw new AssertionError("expected " + type.getName());
    }
}

